/**
 * Visualizes Gaussian Splat positions as a point cloud.
 *
 * Provides a lightweight point cloud overlay showing the center positions
 * of all splats in a GaussianSplats instance.
 *
 * @class GaussianSplatsPoints
 * @extends THREE.Points
 * @short Point cloud visualization of Gaussian Splat centers.
 * @category Helpers
 * @tags WebGPU
 *
 * @example
 * const splats = await loader.loadAsync('/model.ply');
 * scene.add(splats);
 *
 * // Coordinate transform is applied internally to match splats visual output
 * const points = new GaussianSplatsPoints(splats);
 * scene.add(points);
 */
export class GaussianSplatsPoints {
    static get type(): string;
    /**
     * Extract positions from packed positionsScales buffer.
     * Format: [pos0.x, pos0.y, pos0.z, scale0.x, scale0.y, scale0.z, pos1.x, ...]
     * @private
     * @static
     * @param {Float32Array} packedArray - The packed positionsScales array
     * @param {number} count - Number of splats
     * @returns {Float32Array} Extracted positions (count * 3 floats)
     */
    private static _extractPositions;
    /**
     * Extract array from various buffer formats.
     * @private
     * @static
     */
    private static _getBufferArray;
    /**
     * Create a GaussianSplatsPoints visualization.
     *
     * @param {GaussianSplats} splats The GaussianSplats instance to visualize.
     * @param {Object} [options={}] Options.
     * @param {number} [options.pointSize=0.01] Size of the points in world units.
     * @param {boolean} [options.useColors=false] Use splat colors for points.
     * @param {number} [options.color=0xffffff] Fallback color if useColors is false.
     * @param {boolean} [options.sizeAttenuation=true] Scale points with distance.
     */
    constructor(splats: GaussianSplats, options?: {
        pointSize?: number;
        useColors?: boolean;
        color?: number;
        sizeAttenuation?: boolean;
    });
    isGaussianSplatsPoints: boolean;
    _splats: GaussianSplats;
    _pointSize: number;
    _useColors: boolean;
    _color: any;
    _sizeAttenuation: boolean;
    frustumCulled: boolean;
    /**
     * Update point positions when splat data changes.
     */
    update(): void;
    /**
     * Dispose of resources.
     */
    dispose(): void;
}
